using A = BoatsNBeasts.Core.LandingAction;
using D = BoatsNBeasts.Core.SeaDuty;
using J = BoatsNBeasts.Core.SeaJob;
using S = BoatsNBeasts.Core.YardSite;

namespace BoatsNBeasts.Core;

public static partial class FarLedger
{
    static CampaignArc Sleeping() => CampaignArc.Create("The Sleeping Narrows","Permission to Wake",
        "The first harbor in the narrows has woken three feet higher than the others. Its sleeping shoal animal took a breath. Under every house a runner has been driven into the skin to stop it taking another.",
        "A bed leg that can fold flat under a waking town",
        new("Latt Minnow  /  harbor bedmaker",
            "Who moves first?",
            "The sleeper has been trying to roll toward deep water. Latt can pull every bed into the channel before she lifts the last runner, or tap a waking tune while the infirmary still stands on its back. The patients ask for a vote.",
            "Carry the beds out",
            "Ask the sleeper first",
            "Each household makes a place on deck for one bed. Latt carries the empty cot of a patient who went home this morning.",
            "The infirmary votes by tapping its bedsteads. When it hears the tune the sleeper waits until the tapping stops."),
        12,
        [
            Crossing("wake-snore-chart",D.Sounding,"The Harbor Holds Its Breath",
                "Latt has kept every bed level for thirty years. Her new carpenter’s level is a bowl of broth. The broth keeps climbing toward the oldest infirmary.","Find the airways under the listing harbor.",
                "Shuttersnout","The three airway marks move together. The pilots have charted a single vast sleeping animal as three islands.",8,J.Sound,J.Track,J.Relay),
            Landfall("wake-runner-room","The Fourth Bedpost",
                "The infirmary floor hides an iron runner. Latt has spent her working life making beds to disguise its lean. A fresh shoot of pink skin curls around the bolt.","Railback Weevil","Latt sands the iron off the skin. The entire town rises and settles like a child taking its first full breath.",8,
                At(A.Brace,S.West,"Ward trestle","Brace the infirmary on folding trestles"),
                At(A.Turn,S.East,"Runner nut","Unwind the nut under the oldest bed"),
                At(A.Haul,S.Crane,"Iron bed runner","Lift the runner clear of the breathing skin")),
            Crossing("wake-carry-beds",D.Convoy,"Every Bed a Boat",
                "The pilot barges lie too low for their patients to see the sunrise. Latt saws the tall legs off the harbor masters’ beds and fits them to the barges.","Carry the beds into the open waking channel.",
                "Mattress Manta","The patient in the last bed catches the first ray of sun. The harbor master has spent the night on a very low mattress.",8,J.Tow,J.Relieve,J.Guide),
            Landfall("wake-waking-stairs","The Stair That Folded",
                "The sleeper can move its shoulder now. The houses built nearest its neck still have straight staircases running between two moving plates.","Hinge Beetle","The first staircase folds into a ladder, then a bridge. The girl who lives at the top walks downstairs and comes out in her best friend’s kitchen.",8,
                At(A.Brace,S.West,"Shoulder stair","Brace the long stair across the shoulder"),
                At(A.Cut,S.East,"Straight stringer","Cut the fixed stringer above the old hinge"),
                At(A.Turn,S.Stairs,"Folding step","Turn the upper flight into a floating bridge")),
            Crossing("wake-bed-answer",D.Salvage,"The Patient’s Signature",
                "A wax ear trumpet with a signed ward order has slipped through a crack between the sleeper’s jaws. Latt knows where lost things collect, having dropped a quantity of nails down there herself.","Recover the ear trumpet and carry the patient’s answer back.",
                "Jaw-Hinge Lobster","The trumpet comes up with a nail rattling inside. The order says please move my bed and let her rise. Latt adds the nail to her pocket.",8,J.Track,J.Salvage,J.Unload),
            Crossing("wake-rise-together",D.Blockade,"A Harbor Stands Up",
                "A ring of unmanned mooring drums is tightening as the sleeper turns. They will pull its old course straight across the nursery. The pilots ask the crew to take the turn with it.","Break the ring of drums and signal the waking harbor onto its own course.",
                "The Alarm Clock","The sleeper turns its head steadily toward the nursery. Latt goes home. Her bed tips sixteen degrees to port and she sleeps very well.",8,J.Cut,J.DriveOff,J.Relay)
        ],
        Crossing("wake-sleep-question",D.Sounding,"The Bedstead Vote",
                "Several patients cannot hold a hammer. Latt brings them spoons and arranges the iron boats into a listening circle.","Carry the patients’ answering rhythm to the sleeper’s listening hollow.",
                "Stethoscope Ray","A fin moves under the infirmary without disturbing a single cup. The patient who voted last asks for her spoon back; she has not finished her pudding.",8,J.Sound,J.Track,J.Relay));

    static IslandStory[] SleepingIsles() => [
        Isle("The Sleeping Narrows",12,"Blanket Spit","Fen Apron, ward laundress",
            "Every high tide the hospital laundry climbs into the branches of a great sleeping fin. Fen has used all her ladders and every sheet is still a little out of reach.",
            "A clothespin made from a fin molt",
            new PostLetter("A bedsheet patched with pale green sailcloth",
                "Does the breeze above the fin take the smell of medicine out of the sheets?",
                "Yes, but it puts the smell of pears back in. We voted to keep it."),
            Crossing("wake-sheet-count",D.Hunt,"Twenty-Seven Sheets",
                "The gray sheet that hangs lowest keeps flapping against the wind. Fen says it was mended twice at the same corner.","Find the sheet carrying a passenger and protect it in the turn.",
                "Hem Gull","One of the creases is the folded wing of a linen bat. Six younger bats have learned to lie very flat.",8,J.Track,J.Bait,J.DriveOff),
            Landfall("wake-sheet-manger","Linen Nursery",
                "The bats need their sheet to sleep. Fen can spare the oldest laundry basket if somebody hangs it where the scent of starch reaches.","Bobbin Bat","The first bat examines the basket seam and moves it three inches. Fen leaves the carpenter’s pencil with the family.",8,
                At(A.Brace,S.West,"Basket rail","Brace the old basket rail above the fin"),
                At(A.Haul,S.Crane,"Linen basket","Raise the clean basket beside the roost"),
                At(A.Seat,S.East,"Worn gray sheet","Tuck the bats’ sheet into the basket")),
            Crossing("wake-sheet-drift",D.Convoy,"Drying Weather",
                "The ward needs the clean sheets before visiting hours. Fen lashes the drying lines between two lighters and sails the wash clear of the changing tide.","Bring the laundry boats alongside the floating ward.",
                "Clothesline Jack","Twenty-six sheets return. Fen signs for twenty-seven and leaves a note that the last is occupied.",8,J.Tow,J.Guide,J.Relieve),
            Landfall("wake-sheet-fold","Hospital Corners",
                "The bats have sent Fen an exact copy of the missing sheet, woven from soft fin molt. The ward keeper will accept it if it folds round the new waking beds.","Linen Mite","The first patient sleeps without waking when the island turns. Fen puts the new sheet design in the laundry book under B.",8,
                At(A.Turn,S.West,"Folding bed","Turn the bed to its steepest angle"),
                At(A.Seat,S.East,"Molt blanket","Seat the four corners under the reclining frame"),
                At(A.Guide,S.Stairs,"Ward keeper","Bring the keeper down to inspect the seam"))),
        Isle("The Sleeping Narrows",12,"Underlip Market","Lo Tick, oyster weighmaster",
            "Every morning a row of stalls appears under a sleeping island’s lip. At noon the tide fills the stalls and Lo’s scales say every oyster weighs precisely nothing.",
            "A brass balance pan that works underwater",
            new PostLetter("A wax rubbing of the market scale",
                "Could an honest pan tell the difference between a buyer’s thumb and a rising tide?",
                "Bring me the thumb and a bucket. We have established the weight of the tide already."),
            Landfall("wake-lip-counter","A Thumb on the Pan",
                "A collector demands a day’s tax on the weight of the water in the oyster sacks. Lo decides to weigh the collector’s boots first.","Brass Thumb","Both boots float. The collector admits they were made for a shorter man and stuffed with cork.",8,
                At(A.Brace,S.West,"Weigh table","Brace the table level with the waterline"),
                At(A.Turn,S.East,"Wet fulcrum","Turn the fulcrum over the lower lip"),
                At(A.Seat,S.Stairs,"Collector’s boots","Set the floating boots in the empty pan")),
            Crossing("wake-lip-corks",D.Salvage,"Where the Corks Went",
                "A row of red corks once marked the market’s dry edge. The collector’s boots contain the last two. Lo wants to restore the public marks.","Raise the old line of market corks from the mouth channel.",
                "Market Skate","The line spells out a warning for teeth. Lo revises her opinion of the first market surveyor.",8,J.Sound,J.Salvage,J.Unload),
            Crossing("wake-lip-shoal",D.Sounding,"Closing Time",
                "The sleeper snores twice before its lip rises. Nobody knows how long the interval is from the far stalls.","Sound the lip from both ends and relay the sign to the far stalls.",
                "Jawbone Pike","The stallholders hear the warning eight breaths before the water comes. A fishmonger asks whether six would buy him a discount.",8,J.Sound,J.Track,J.Relay),
            Landfall("wake-lip-clock","A Public Snore",
                "Lo hangs the lightest balance pan above the deepest pool. One bubble should ring the closing bell; the second should send everyone home.","Panback","The market closes on time. The collector stands in the empty square and taxes nobody. He looks quite relieved.",8,
                At(A.Haul,S.Crane,"Light balance pan","Hang the pan above the snore pool"),
                At(A.Seat,S.East,"Bubble tube","Seat the tube beneath the brass rim"),
                At(A.Turn,S.West,"Closing bell","Turn the bell mouth toward the far stalls"))),
        Isle("The Sleeping Narrows",12,"Pillow Quarry","Roe Flake, moss mason",
            "The town cuts its pillows from a moss-covered limestone shelf. A fresh pillow has learned to walk. The masons want to know whether they have been selling eggs.",
            "A limestone pillow with an empty eggshell hollow",
            new PostLetter("A chalk impression of the walking pillow",
                "Grandad’s pillow has gone to join its family. Can you save him a soft piece of ordinary stone?",
                "A soft piece is on the way. We asked it three times if it meant to walk anywhere."),
            Landfall("wake-quarry-walk","A Pillow for Grandad",
                "The pillow has walked into the quarry lift. Roe wants to free it before the rollers begin their morning shift.","Chalk Slater","Two small feet print their way across Roe’s sleeve. The pillow settles under Grandad’s hat and begins to purr.",8,
                At(A.Brace,S.West,"Quarry lift","Brace the lift before the stone rollers move"),
                At(A.Cut,S.East,"Packing twine","Cut the twine beneath the walking pillow"),
                At(A.Guide,S.Ferry,"Hat and passenger","Carry the hatchling out under Grandad’s hat")),
            Crossing("wake-quarry-hum",D.Sounding,"Which Stones Answer",
                "The masons unload last year’s pillows and listen for the smallest hum. Grandad’s ears are no help except at one particular note.","Take the humming stones past the hollow that brings out their voices.",
                "Echo Shrew","Only seven stones answer. Grandad identifies each voice and asks to be introduced to the parents.",8,J.Tow,J.Sound,J.Relay),
            Crossing("wake-quarry-family",D.Convoy,"Seven Soft Stones",
                "The seven eggs sit in a wheelbarrow on a ferry. Grandad has put his best hat over all seven.","Pilot the egg ferry to the empty shore nests.",
                "Hatpin Skate","Seven eggs find six families. The seventh goes back with Grandad until its parents show up at supper.",8,J.Tow,J.Guide,J.Relieve),
            Landfall("wake-quarry-sleep","The Gentle Quarry",
                "Roe wants to mark the nesting seam so nobody cuts a bed through it again. The masons can read chalk but the returning families cannot.","Nesting Chisel","Roe lays a line of warm moss around the seam. The masons stop on one side and the families curl up on the other.",8,
                At(A.Turn,S.West,"Cold stone trough","Turn the trough away from the egg seam"),
                At(A.Haul,S.Crane,"Warm moss line","Haul the long moss strip around the nests"),
                At(A.Seat,S.East,"Quarry marker","Seat the chalk marker in ordinary limestone"))),
        Isle("The Sleeping Narrows",12,"Clockjaw Landing","Tab Morel, night conductor",
            "Tab blows a whistle at every scheduled surfacing of the mail fin. It has surfaced late for four days, each time carrying one more empty chair.",
            "A ticket punched with a chair-shaped hole",
            new PostLetter("One reserved ticket for an empty chair",
                "We have a passenger who can walk but likes taking her favorite chair wherever she goes. Will you carry both?",
                "Of course. We have carried the chair every Tuesday for seventeen years. It will be good to meet its owner."),
            Crossing("wake-chair-mail",D.Hunt,"The Late Fin",
                "The mail fin is not late; it is keeping an older timetable. Tab asks the crew to follow its detour before he makes a new schedule.","Track the fin beyond the present terminus.",
                "Timetable Stork","The older terminus is a retirement quay. Each afternoon the chairs are put aboard first so the passengers can climb on at their leisure.",8,J.Track,J.Bait,J.DriveOff),
            Landfall("wake-chair-steps","Two Low Steps",
                "The old platform has sunk below wheelchair height. Tab can make the next stop accessible with the two spare wooden steps he keeps for the ticket booth.","Stepjaw Snail","A passenger boards under her own power. Tab’s ticket booth is now awkward to get into. He decides he rather likes selling tickets outside.",8,
                At(A.Brace,S.West,"Platform sill","Brace the sinking platform sill"),
                At(A.Haul,S.Crane,"Booth steps","Lower the spare steps to fin height"),
                At(A.Seat,S.East,"Low handrail","Seat the handrail beside the last step")),
            Crossing("wake-chair-whistle",D.Salvage,"The Short Whistle",
                "The old conductor sank her whistle to stop the line being closed. Tab wants its soft note for the quiet retirement stop.","Find the old whistle at the foot of the platform.",
                "Whistling Whelk","The whistle plays an almost inaudible G. Everyone at the retirement quay hears it perfectly.",8,J.Track,J.Salvage,J.Unload),
            Landfall("wake-chair-run","The Earlier Timetable",
                "The station clock has only one hand. Tab wants to put the old and new services on the same face without making the mail fin late for lunch.","Hourhand Toad","Tab draws a second circle. The return ticketholder finally meets the owner of the chair that has been traveling on her ticket.",8,
                At(A.Turn,S.West,"Clock spindle","Turn the old spindle free of the dial"),
                At(A.Seat,S.East,"Second dial","Seat the retirement line’s dial around the first"),
                At(A.Guide,S.Ferry,"First return passenger","Guide both chair and passenger aboard the mail fin")))
    ];
}
